<?php

declare(strict_types=1);

namespace Database\Seeders;

use Illuminate\Database\Seeder;

class DatabaseSeeder extends Seeder
{
    /**
     * Seed the application's database.
     *
     * Order matters: roles and users come first because the content seeders
     * hand ownership to the regular users, and comments, likes and the friend
     * network come last because they attach to the seeded records.
     *
     * Model events stay enabled here: slugs are generated by the Sluggable
     * observer and the cache observers keep cached responses in step with the
     * seeded rows.
     */
    public function run(): void
    {
        $this->call([
            RoleSeeder::class,
            UserSeeder::class,
            BlogCategorySeeder::class,
            TagSeeder::class,
            BlogPostSeeder::class,
            ProductSeeder::class,
            PetMemorialSeeder::class,
            CommentSeeder::class,
            LikeSeeder::class,
            FriendRequestSeeder::class,
        ]);
    }
}
